const WINDOW_MS = 15 * 60_000, MAX_NEW = 5;
const FIXERS = ["fe-ci-fixer", "be-ci-fixer", "pipeline-fixer"];

export const stormCheck = async (repo: string): Promise<"normal" | "incident"> => {
  const since = new Date(Date.now() - WINDOW_MS).toISOString();
  const names = FIXERS.map((r) => `'${r}'`).join(", ");
  const query = `WorkflowType = 'routineRun' AND RunKind = 'cifix' AND Routine IN (${names}) AND StartTime > '${since}'`;
  const { count: newFingerprints } = await temporal.workflow.count(query);
  if (newFingerprints <= MAX_NEW) return "normal";

  const reason = `${newFingerprints} new failure fingerprints in 15 minutes on ${repo}: likely infrastructure, not code`;
  if (await flags.setIfAbsent("routines:fixers:paused", reason)) {
    await pagerduty.trigger({ service: "ai-agents", summary: reason });
    await slack.post("#ai-agents-alerts", reason, { details: await firstErrors(query), buttons: ["Resume fixers"] });
  }
  return "incident";
};

const COUNTS_AGAINST = new Set(["failed", "rejected"]);

export const circuitBreaker = async (routine: string, owner: string): Promise<boolean> => {
  const last5 = await lastFinishedRuns(routine, 5);  // newest first, with RoutineOutcome
  const bad = last5.filter((run) => COUNTS_AGAINST.has(run.outcome));
  if (last5.length < 5 || bad.length < 3) return false;

  const reason = `3 of its last 5 runs failed or were rejected: ${bad.map((r) => r.workflowId).join(", ")}`;
  await flags.set(`routine:${routine}:paused`, reason);
  await slack.dm(owner, `${routine} is paused. ${reason}`, { buttons: ["Resume", "Keep paused"] });
  return true;
};

