import { Client, Connection } from "@temporalio/client";
import { setIfAbsent } from "./flags.ts";

const WINDOW_MS = 15 * 60_000;
const MAX_NEW = 5;

const connection = await Connection.connect({ address: process.env.TEMPORAL_ADDRESS ?? "localhost:7233" });
const client = new Client({ connection });

const since = new Date(Date.now() - WINDOW_MS).toISOString();
const query = `WorkflowType = 'routineRun' AND RunKind = 'cifix' AND StartTime > '${since}'`;
const { count } = await client.workflow.count(query);

if (count <= MAX_NEW) {
  console.log(`normal: ${count} new fingerprints in 15 minutes`);
} else {
  const reason = `${count} new failure fingerprints in 15 minutes: likely infrastructure, not code`;
  if (setIfAbsent("routines-fixers-paused", reason)) {
    console.log(`incident: fixers paused, paging on-call once: ${reason}`);
  } else {
    console.log(`incident: already paused, no second page (${count} fingerprints)`);
  }
}
await connection.close();
